def transform(grid):
    g = np.array(grid)
    bg = background(g)
    H, W = g.shape
    mark = None
    # identify seam colour: colour adjacent to/inside objects that disappears -> the minority non-bg colour
    vals, cnts = np.unique(g[g != bg], return_counts=True)
    seam = vals[np.argmin(cnts)]
    out = np.full_like(g, bg)
    emit(out.copy(), "Erase everything: blocks will be redrawn as separated halves, seams removed.")
    blocks = components(g != bg)
    for blk in blocks:
        seam_cells = [(y, x) for y, x in blk if g[y, x] == seam]
        body = np.zeros_like(g, dtype=bool)
        for y, x in blk:
            if g[y, x] != seam:
                body[y, x] = True
        if not seam_cells:
            for y, x in blk:
                out[y, x] = g[y, x]
            continue
        sy = np.mean([c[0] for c in seam_cells]); sx = np.mean([c[1] for c in seam_cells])
        for piece in components(body):
            py = np.mean([c[0] for c in piece]); px = np.mean([c[1] for c in piece])
            dy, dx = py - sy, px - sx
            if abs(dy) >= abs(dx):
                my, mx = (1 if dy > 0 else -1), 0
            else:
                my, mx = 0, (1 if dx > 0 else -1)
            for y, x in piece:
                ny, nx = y + my, x + mx
                if 0 <= ny < H and 0 <= nx < W:
                    out[ny, nx] = g[y, x]
        emit(out.copy(), "Split one block along its seam: each half moved one cell away from the seam.")
    emit(out.copy(), "Final grid: all blocks split open.")
    return out
